import axios from 'axios';

// ─── Instance Axios configurée ──────────────────────────────────────────────
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8000/api',
  headers: { 'Content-Type': 'application/json' },
  timeout: 10000,
});

// ─── Intercepteur de réponse : gestion centralisée des erreurs ───────────────
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const message =
      error.response?.data?.message ||
      error.response?.data?.error ||
      'Une erreur est survenue';
    return Promise.reject(new Error(message));
  }
);

// ─── Service d'authentification ────────────────────────────────────────────
const authService = {
  /**
   * POST /auth/login
   * @returns {{ token: string, user: { id, name, email, role } }}
   */
  login: async ({ email, password }) => {
    const { data } = await api.post('/auth/login', { email, password });
    return data;
  },

  /**
   * POST /auth/register
   * @returns {{ token: string, user: { id, name, email, role } }}
   */
  register: async ({ name, email, password, phone }) => {
    const { data } = await api.post('/auth/register', { name, email, password, phone });
    return data;
  },

  /**
   * Injecte le Bearer token dans tous les futurs appels Axios
   */
  setAuthHeader: (token) => {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  },

  /**
   * Supprime le header d'autorisation (logout)
   */
  removeAuthHeader: () => {
    delete api.defaults.headers.common['Authorization'];
  },
};

export { api }; // exporté pour les autres services (rooms, reservations…)
export default authService;
